using System.Threading.Tasks;
using Google.Apis.Auth.OAuth2;
using Google.Apis.Services;
using Google.Apis.Util.Store;
using Google.Analytics.Data.V1alpha;

public class Ga4Service
{
    private readonly GoogleAnalyticsClient _client;

    public Ga4Service(string clientId, string clientSecret, string redirectUri)
    {
        UserCredential credential;
        using (var stream = new FileStream("client_secret.json", FileMode.Open, FileAccess.Read))
        {
            string credPath = "token.json";
            credential = GoogleWebAuthorizationBroker.AuthorizeAsync(
                GoogleClientSecrets.Load(stream).Secrets,
                new[] { AnalyticsDataV1AlphaService.Scope.AnalyticsReadonly },
                "user",
                CancellationToken.None,
                new FileDataStore(credPath, true)).Result;
        }
        _client = new GoogleAnalyticsClient(new AuthorizedUserCredential(GoogleAnalyticsService.AccountType, credential));
    }

    public async Task<GoogleAnalyticsDataV1Alpha.GetReportsResponse> GetReportAsync(string propertyId)
    {
        var request = new GetReportsRequest
        {
            Property = $"properties/{propertyId}",
            DateRanges = new List<DateRange>
            {
                new DateRange
                {
                    StartDate = "7daysAgo",
                    EndDate = "today"
                }
            },
            Dimensions = new List<Dimension>
            {
                new Dimension
                {
                    Name = "date"
                },
                new Dimension
                {
                    Name = "eventCategory"
                },
                new Dimension
                {
                    Name = "eventAction"
                },
                new Dimension
                {
                    Name = "eventLabel"
                }
            },
            Metrics = new List<Metric>
            {
                new Metric
                {
                    Name = "events.eventCount"
                },
                new Metric
