class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def autocomplete(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []  # No matches
            node = node.children[char]

        # Now, `node` points to the last node in the prefix path
        return self._get_words_from_node(node, prefix)

    def _get_words_from_node(self, node, current_path):
        result = []
        if node.is_end_of_word:
            result.append(current_path)
        for char, child in node.children.items():
            result.extend(self._get_words_from_node(child, current_path + char))
        return result

